def choose_move(observation):
    # Simple deterministic heuristic: move toward nearest resource if available,
    # else move toward center of grid as a fallback, but never leave bounds.
    grid_w = observation.get("grid_width", 0)
    grid_h = observation.get("grid_height", 0)
    pos = observation.get("self_position", {})
    x = pos.get("x", 0)
    y = pos.get("y", 0)

    resources = observation.get("resources", [])
    if isinstance(resources, list) and resources:
        best = None
        best_d = None
        for r in resources:
            rx = r.get("x", None)
            ry = r.get("y", None)
            if rx is None or ry is None:
                continue
            d = (rx - x) * (rx - x) + (ry - y) * (ry - y)
            if best_d is None or d < best_d:
                best_d = d
                best = (rx, ry)
        if best is not None:
            rx, ry = best
            if rx > x:
                dx = 1
            elif rx < x:
                dx = -1
            else:
                dx = 0
            if ry > y:
                dy = 1
            elif ry < y:
                dy = -1
            else:
                dy = 0
            return [dx, dy]

    # If no resources or none reachable, move toward grid center deterministically.
    cx = (grid_w - 1) // 2
    cy = (grid_h - 1) // 2
    if x < cx:
        dx = 1
    elif x > cx:
        dx = -1
    else:
        dx = 0
    if y < cy:
        dy = 1
    elif y > cy:
        dy = -1
    else:
        dy = 0

    # Ensure staying within bounds if grid sizes provided
    nx = x + dx
    ny = y + dy
    if grid_w:
        nx = max(0, min(grid_w - 1, nx))
    if grid_h:
        ny = max(0, min(grid_h - 1, ny))

    # Adjust dx,dy to the clamped move
    dx = nx - x
    dy = ny - y
    return [dx, dy]
